CREATE TABLE farm_user (id VARCHAR(36) PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, display_name VARCHAR(80) NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE auth_session (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, expires_at TIMESTAMP NOT NULL);
CREATE TABLE worker (id VARCHAR(36) PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, phone VARCHAR(40) NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE category (id VARCHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE product (id VARCHAR(36) PRIMARY KEY, category_id VARCHAR(36) NOT NULL, name VARCHAR(80) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(category_id, name));
CREATE TABLE price_rule (id VARCHAR(36) PRIMARY KEY, product_id VARCHAR(36) NOT NULL, effective_date DATE NOT NULL, rule_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(36) NOT NULL, change_reason VARCHAR(500) NOT NULL, INDEX rule_product(product_id,effective_date));
CREATE TABLE ledger_month (month_key VARCHAR(7) PRIMARY KEY, closed BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE harvest_record (id VARCHAR(36) PRIMARY KEY, worker_id VARCHAR(36) NOT NULL, work_date DATE NOT NULL, period VARCHAR(2) NOT NULL, product_id VARCHAR(36) NOT NULL, inputs_json TEXT NOT NULL, note VARCHAR(1000) NOT NULL, created_by VARCHAR(36) NOT NULL, updated_by VARCHAR(36) NOT NULL, version INT NOT NULL DEFAULT 1, deleted BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(worker_id, work_date, period, product_id), INDEX record_month(work_date));
CREATE TABLE operation_receipt (operation_id VARCHAR(36) PRIMARY KEY, actor_id VARCHAR(36) NOT NULL, request_hash VARCHAR(64) NOT NULL, result_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settlement (id VARCHAR(36) PRIMARY KEY, month_key VARCHAR(7) NOT NULL, kind VARCHAR(20) NOT NULL, created_by VARCHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settlement_line (id VARCHAR(36) PRIMARY KEY, settlement_id VARCHAR(36) NOT NULL, record_id VARCHAR(36) NOT NULL, worker_id VARCHAR(36) NOT NULL, amount DECIMAL(18,2) NOT NULL, snapshot_json TEXT NOT NULL, INDEX line_record(record_id));
CREATE TABLE payment (id VARCHAR(36) PRIMARY KEY, worker_id VARCHAR(36) NOT NULL, month_key VARCHAR(7) NOT NULL, amount DECIMAL(18,2) NOT NULL, method VARCHAR(40) NOT NULL, note VARCHAR(500) NOT NULL, created_by VARCHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id VARCHAR(36) PRIMARY KEY, actor_id VARCHAR(36) NOT NULL, action VARCHAR(60) NOT NULL, entity_id VARCHAR(36) NOT NULL, before_json TEXT NOT NULL, after_json TEXT NOT NULL, reason VARCHAR(1000) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
